(function() {
  try {
    function setVal(selector, val) {
      const host = document.querySelector(selector);
      if (!host) return false;
      let input = host;
      if (host.shadowRoot) {
        input = host.shadowRoot.querySelector('input') || host.shadowRoot.querySelector('textarea') || host;
      }
      if (input) {
        input.value = val;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      }
      return false;
    }

    setVal('#field-name', 'Jane Smith');
    setVal('#field-address', '123 Test Lane');
    setVal('#field-city', 'Anytown');
    setVal('#field-zip', '00000');
    setVal('#field-card', '4111111111111111');
    setVal('#field-expiry', '12/28');
    setVal('#field-cvv', '123');

    const btn = document.querySelector('#place-order-btn');
    if (btn) {
      btn.click();
      return 'Success: Form filled and order placed';
    }
    return 'Filled fields, but place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
